    const d = H.I18N[H.lang] || uk;
    let s = key in d ? d[key] : key in uk ? uk[key] : key;
    if (!p) return s;
    s = s.replace(/\{(\w+)\?([^|}]*)\|([^}]*)\}/g, (_, k, a, b) => (p[k] ? a : b));
